const NOTE_KEY = 'lineTrackerNotesV3';
let data = INITIAL_DATA.map(r => [...r]);
let priceBusy = false;
function legacyRowKey(r){return [r[0],r[1],r[6],r[8],r[13]||''].join('|')}
function rowKey(r){return [r[0],r[1],String(r[7]||'').replace(/\s+/g,' ').trim()].join('|')}
const CLOUD = window.LINE_TRACKER_CONFIG || {};
let cloudClient = null, cloudUser = null, remoteNotes = localNotes();
function localNotes(){try{const n=JSON.parse(localStorage.getItem(NOTE_KEY)||'{}');return n&&typeof n==='object'?n:{}}catch(_){return {}}}
function cleanReason(value){return String(value||'').replaceAll('JH 公司帳號','').replace(/^\s*📢\s*/,'').replace(/\s+/g,' ').trim()}
data.forEach(row=>{row[7]=cleanReason(row[7])});
function loadNotes(){return remoteNotes}
function syncNotice(message){const e=document.querySelector('#cloudStatus');if(e)e.textContent=message}
function noteHit(r,notes){const key=rowKey(r),legacy=legacyRowKey(r);if(typeof notes[key]==='string')return [notes[key],key];if(typeof notes[legacy]==='string')return [notes[legacy],legacy];const prefix=[r[0],r[1]].join('|')+'|';const fallback=Object.entries(notes).find(([stored,value])=>stored.startsWith(prefix)&&typeof value==='string');return fallback||['','']}
function saveNotes(){const notes=remoteNotes;data.forEach(r=>{const value=(r[12]||'').trim(),key=rowKey(r),source=r._noteSource||'';if(value){notes[key]=value;if(source&&source!==key)notes[source]=value}else{delete notes[key];if(source)delete notes[source]}});localStorage.setItem(NOTE_KEY,JSON.stringify(notes));if(cloudUser)void pushNotes()}
function applyNotes(){const notes=loadNotes();data.forEach(r=>{const [value,key]=noteHit(r,notes);r[12]=value;r._noteSource=key})}
async function loadRemoteNotes(){const {data:rows,error}=await cloudClient.from('tracker_notes').select('row_key,note').eq('tracker_id','line-stock-tracker');if(error){syncNotice('註記讀取失敗：'+error.message);return}remoteNotes={...localNotes()};for(const r of rows||[])remoteNotes[r.row_key]=r.note;applyNotes();render();syncNotice('註記已雲端同步：'+cloudUser.email)}
async function pushNotes(){if(!cloudClient||!cloudUser)return;const rows=Object.entries(remoteNotes).map(([row_key,note])=>({tracker_id:'line-stock-tracker',row_key,note}));const {error}=await cloudClient.from('tracker_notes').upsert(rows,{onConflict:'user_id,tracker_id,row_key'});if(error)syncNotice('註記儲存失敗：'+error.message);else syncNotice('註記已儲存並同步')}
async function clearNotes(){if(!confirm('確定清除所有「我的註記」嗎？此動作會同步到你的其他裝置。'))return;remoteNotes={};data.forEach(r=>{r[12]='';r._noteSource=''});localStorage.removeItem(NOTE_KEY);if(cloudClient&&cloudUser){const {error}=await cloudClient.from('tracker_notes').delete().eq('tracker_id','line-stock-tracker');syncNotice(error?'註記清除失敗：'+error.message:'註記已從雲端清除')}render()}
async function signInCloud(){const email=(document.querySelector('#cloudEmail')?.value||'').trim();if(!email){syncNotice('請輸入你的 Email');return}if(!cloudClient){syncNotice('雲端同步尚在準備；請稍後再按一次。');return}try{syncNotice('正在寄送登入連結…');const {error}=await cloudClient.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin}});syncNotice(error?'登入連結寄送失敗：'+error.message:'登入連結已寄到 Email；請在同一台裝置開啟信件中的連結，再回到本頁。')}catch(error){syncNotice('登入連線失敗：'+(error.message||'請稍後重試'))}}
async function signOutCloud(){try{if(cloudClient)await cloudClient.auth.signOut()}catch(_){}cloudUser=null;remoteNotes={...localNotes(),...remoteNotes};applyNotes();render();syncNotice('已登出；本機註記仍會保留。')}
async function initCloudNotes(){applyNotes();if(!CLOUD.supabaseUrl||!CLOUD.supabaseAnonKey||!window.supabase){syncNotice('本機註記已啟用；雲端同步尚未設定。');return}try{cloudClient=window.supabase.createClient(CLOUD.supabaseUrl,CLOUD.supabaseAnonKey);const {data:{session}}=await cloudClient.auth.getSession();cloudUser=session?.user||null;if(cloudUser)await loadRemoteNotes();else{applyNotes();syncNotice('本機註記已保存；登入僅供跨裝置同步。')}cloudClient.auth.onAuthStateChange(async(_event,session)=>{if(session?.user){cloudUser=session.user;await loadRemoteNotes()}})}catch(error){syncNotice('本機註記已保存；雲端同步暫時無法連線。')}}
function esc(v){return String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
function dateNumber(d){const m=String(d).match(/(\d{1,2})\/(\d{1,2})/);return m?Number(m[1])*100+Number(m[2]):0}
function codeOf(label){const m=String(label).match(/\b(00\d{3}[A-Z]|\d{4})\b/);return m?.[1]||''}
function numbersOf(v){return (String(v).match(/\d+(?:\.\d+)?/g)||[]).map(Number).filter(Number.isFinite)}
function entryOf(v){const nums=numbersOf(v);return nums.length?Math.max(...nums):null}
function pctClass(v){const n=parseFloat(v);return Number.isFinite(n)?(n>=0?'profit':'loss'):''}
function statusClass(row){return row[15]==='closed'?'closed':'open'}
function toggleAnalystTable(){const wrap=document.querySelector('#analystTableWrap'),button=document.querySelector('#analystToggle');if(!wrap||!button)return;const collapsed=wrap.classList.toggle('analyst-collapsed');button.textContent=collapsed?`展開全部 ${wrap.dataset.total} 位分析師`:'收合至前 10 位分析師'}
function stockLink(label){const code=codeOf(label),page=location.protocol==='file:'?'https://line-stock-tracker-orqowf.pages.dev/stock.html':'stock.html';return code?`<a class="stock-link" href="${page}?code=${encodeURIComponent(code)}" target="_blank" rel="noopener" title="開啟個股研究頁">${esc(label)}</a>`:esc(label)}
function normalizePrice(v){const n=Number(v);return Number.isFinite(n)&&n>0?String(n):''}
const SIGNAL_ORDER=['買進','加碼','續抱','回溯買進','賣出','出場','市場訊號'];
const STATUS_ORDER=['買進','加碼','續抱','回溯買進','部分出場','全數出清','觀察市場'];
function chosen(select){return [...select.selectedOptions].map(option=>option.value).filter(Boolean)}
function orderSignals(values){return [...values].sort((a,b)=>{const ai=SIGNAL_ORDER.indexOf(a),bi=SIGNAL_ORDER.indexOf(b);return (ai<0?99:ai)-(bi<0?99:bi)||a.localeCompare(b,'zh-Hant')})}
function orderStatuses(values){return [...values].sort((a,b)=>{const ap=a.split('｜',1)[0],bp=b.split('｜',1)[0],ai=STATUS_ORDER.indexOf(ap),bi=STATUS_ORDER.indexOf(bp);if((ai<0?99:ai)!==(bi<0?99:bi))return (ai<0?99:ai)-(bi<0?99:bi);const an=Number((a.split('｜')[1]||'').match(/\d+(?:\.\d+)?/)?.[0]||-1),bn=Number((b.split('｜')[1]||'').match(/\d+(?:\.\d+)?/)?.[0]||-1);return bn-an||a.localeCompare(b,'zh-Hant')})}
function setOptions(select,placeholder,values,orderer){const prior=chosen(select).filter(value=>values.includes(value));const selected=new Set(prior);const allSelected=!selected.size;select.innerHTML=`<option value="" ${allSelected?'selected':''}>${placeholder}</option>`+orderer(values).map(value=>`<option value="${esc(value)}" ${selected.has(value)?'selected':''}>${esc(value)}</option>`).join('')}
function normalizeAll(select){const selected=chosen(select);if(selected.length){for(const option of select.options)if(!option.value)option.selected=false}else if(select.options[0])select.options[0].selected=true}
function populateSignalFilter(){setOptions(document.querySelector('#signal'),'全部訊號',[...new Set(data.map(r=>r[8]).filter(Boolean))],orderSignals)}
function populateStatusFilter(){setOptions(document.querySelector('#status'),'全部執行狀態',[...new Set(data.map(r=>r[10]).filter(Boolean))],orderStatuses)}
function syncLinkedFilter(changed){const signal=document.querySelector('#signal'),status=document.querySelector('#status');normalizeAll(changed==='signal'?signal:status);if(changed==='signal'){const picks=chosen(signal);const values=[...new Set(data.filter(r=>!picks.length||picks.includes(r[8])).map(r=>r[10]).filter(Boolean))];setOptions(status,'全部執行狀態',values,orderStatuses)}else{const picks=chosen(status);const values=[...new Set(data.filter(r=>!picks.length||picks.includes(r[10])).map(r=>r[8]).filter(Boolean))];setOptions(signal,'全部訊號',values,orderSignals)}}
function render(){const q=document.querySelector('#q').value.toLowerCase();const statuses=chosen(document.querySelector('#status')),signals=chosen(document.querySelector('#signal'));const rows=[...data].filter(r=>(!q||r.join(' ').toLowerCase().includes(q))&&(!statuses.length||statuses.includes(r[10]))&&(!signals.length||signals.includes(r[8]))).sort((a,b)=>dateNumber(b[0])-dateNumber(a[0]));const cols=[0,1,8,10,2,3,11,4,6,7,5,9,12];document.querySelector('#body').innerHTML=rows.map(r=>`<tr>${cols.map(i=>{const cls=(i===4||i===11?pctClass(r[i])+' ':'')+(i===10?statusClass(r)+' ':'')+(i===2||i===3||i===4||i===9||i===11?'num ':'')+((i===7||i===5)?'reason ':'')+(i===12?'note ':'');const editable=i===12;const shown=i===12?(r[i]||''):(r[i]||'—');const display=i===1?stockLink(shown):esc(shown);return `<td class="${cls}" ${editable?'contenteditable="true"':''} data-key="${esc(rowKey(r))}" data-col="${i}">${display}</td>`}).join('')}</tr>`).join('');document.querySelector('#count').textContent=`${rows.length} 筆訊號／共 ${data.length} 筆`}
function collectEditedNotes(){document.querySelectorAll('[contenteditable][data-col="12"]').forEach(cell=>{const r=data.find(x=>rowKey(x)===cell.dataset.key);if(r)r[12]=cell.textContent.trim()==='—'?'':cell.textContent.trim()})}
function saveEditedNotes(){collectEditedNotes();saveNotes();render()}
async function json(url){let lastError;const sources=[url,'https://api.allorigins.win/raw?url='+encodeURIComponent(url),'https://corsproxy.io/?'+encodeURIComponent(url)];for(const source of sources){try{const response=await fetch(source,{cache:'no-store'});if(response.ok)return await response.json();lastError=new Error(`HTTP ${response.status}`)}catch(error){lastError=error}}throw lastError||new Error('報價來源無回應')}
function numberValue(value){const text=String(value??'').replaceAll(',','').replaceAll('－','-');const match=text.match(/[+-]?\d+(?:\.\d+)?/);return match?Number(match[0]):null}
function fieldOf(record,names){for(const name of names)if(record[name]!==undefined&&record[name]!==null)return record[name];const normalized=Object.keys(record).find(key=>names.some(name=>key.toLowerCase()===name.toLowerCase()));return normalized?record[normalized]:null}
function addQuoteRecords(records,result){for(const record of Array.isArray(records)?records:[]){const code=String(fieldOf(record,['Code','SecuritiesCompanyCode','證券代號','股票代號','代號'])||'').trim();const price=numberValue(fieldOf(record,['ClosingPrice','Close','收盤價','收盤價(元)','成交價','LastPrice']));if(!code||!Number.isFinite(price)||price<=0)continue;const change=numberValue(fieldOf(record,['Change','ChangePrice','漲跌','漲跌價差','UpDown']));const previous=Number.isFinite(change)?price-change:null;result.set(code,{price,previous:Number.isFinite(previous)&&previous>0?previous:null})}}
async function fetchBatchQuotes(codes){const response=await fetch('/api/quotes?codes='+encodeURIComponent(codes.join(',')),{cache:'no-store'});if(!response.ok)throw new Error('雲端報價服務沒有回應');const payload=await response.json();const result=new Map();addQuoteRecords(payload.listed,result);addQuoteRecords(payload.otc,result);if(!result.size)throw new Error('雲端報價服務沒有可用資料');return result}
function calculateAvailable(row){if(row[14]==='fixed')return true;const current=Number(row[3]);const entry=entryOf(row[2]);if(!Number.isFinite(current)||current<=0){row[4]='待報價';return false}if(!entry){row[4]='待建議價';return false}row[4]=((current-entry)/entry*100).toFixed(2)+'%';return true}
function quoteClassification(row){const stock=String(row[1]||''),signal=String(row[8]||'');if(/台指期|台積電期|期貨/.test(stock))return '期貨／非股票；不納入現股即時報價';if(signal==='市場訊號')return '非股票／市場訊號；不納入現股即時報價';if(!/^\d{4,6}\s+\S+/.test(stock))return '代號需修正；目前無法自動匹配現股報價';return ''}
function setQuoteClassification(row,label){const base=String(row[5]||'').replace(/；?報價分類：[^；]*/g,'').replace(/；+$/,'');row[5]=(base?base+'；':'')+'報價分類：'+label}
function pause(ms){return new Promise(resolve=>setTimeout(resolve,ms))}
async function refreshPrices(){if(priceBusy)return;saveEditedNotes();priceBusy=true;const button=document.querySelector('#quoteButton'),status=document.querySelector('#quoteStatus');button?.classList.add('loading');if(button)button.textContent='正在更新';const rowsByCode=new Map();data.forEach(row=>{const category=quoteClassification(row);if(category){setQuoteClassification(row,category);return}const code=codeOf(row[1]);if(code){if(!rowsByCode.has(code))rowsByCode.set(code,[]);rowsByCode.get(code).push(row)}else setQuoteClassification(row,'代號需修正；目前無法自動匹配現股報價')});const codes=[...rowsByCode.keys()];try{status.textContent=`正在取得 ${codes.length} 支股票的批次報價…`;const quotes=await fetchBatchQuotes(codes);let processed=0,found=0;for(const code of codes){const quote=quotes.get(code);if(quote){found++;for(const row of rowsByCode.get(code)){row[3]=normalizePrice(quote.price);row[11]=quote.previous?((quote.price-quote.previous)/quote.previous*100).toFixed(2)+'%':'—';calculateAvailable(row)}}else for(const row of rowsByCode.get(code))setQuoteClassification(row,'暫無報價；官方來源未匹配此代號');processed++;if(processed===1||(processed-1)%7===0||processed===codes.length){status.textContent=`${processed}/${codes.length} 支股票｜已取得 ${found} 支報價，正在回填與計算績效…`;render();await pause(90)}}saveNotes();status.textContent=`${processed}/${codes.length} 支股票完成｜成功取得 ${found} 支報價｜${new Date().toLocaleTimeString('zh-TW',{hour12:false})}`;render()}catch(error){status.textContent='雲端報價服務暫時沒有回應，請稍後再按「股價更新」。'}finally{priceBusy=false;button?.classList.remove('loading');if(button)button.textContent='股價更新'}}
function downloadCsv(){saveEditedNotes();const header=['訊號日','股票','訊號','執行狀態','建議價位','現價','現價漲跌幅','績效','推薦老師','推薦原因','判斷邏輯','出場價位','我的註記'];const visible=[0,1,8,10,2,3,11,4,6,7,5,9,12];const csv=[header,...data.map(r=>visible.map(i=>'"'+String(r[i]||'').replaceAll('"','""')+'"'))].map(row=>row.join(',')).join('\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));link.download='LINE_股市同學會_投資追蹤表.csv';link.click();URL.revokeObjectURL(link.href)}
void initCloudNotes();document.querySelector('#q').addEventListener('input',render);document.querySelector('#status').addEventListener('change',()=>{syncLinkedFilter('status');render()});document.querySelector('#signal').addEventListener('change',()=>{syncLinkedFilter('signal');render()});let noteSaveTimer;document.querySelector('#body').addEventListener('input',event=>{if(event.target.matches('[contenteditable]')){clearTimeout(noteSaveTimer);noteSaveTimer=setTimeout(()=>{collectEditedNotes();saveNotes()},350)}});document.querySelector('#body').addEventListener('focusout',event=>{if(event.target.matches('[contenteditable]'))saveEditedNotes()});applyNotes();populateSignalFilter();populateStatusFilter();render();
